# Find icon-only buttons without aria-label
files_with_buttons = []
for root, dirs, filenames in os.walk("apps/web/src"):
    for fn in filenames:
        if fn.endswith('.jsx'):
            fp = os.path.join(root, fn)
            with open(fp) as f:
                content = f.read()
            if '<button' in content:
                files_with_buttons.append(fp)

print("=== Icon-only buttons without aria-label ===")
for f in sorted(files_with_buttons):
    with open(f) as fh:
        lines = fh.readlines()

    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith('<button') and 'aria-label' not in stripped:
            # Get the button block
            block_lines = [stripped]
            j = i + 1
            while j < len(lines) and '</button>' not in lines[j]:
                block_lines.append(lines[j].strip())
                j += 1
            if j < len(lines):
                block_lines.append(lines[j].strip())

            block = ' '.join(block_lines)

            # Check if it's icon-only (very short inner content)
            if '</button>' in block:
                tag_end = block.find('>')
                close_tag = block.find('</button>')
                if tag_end < close_tag:
                    inner = block[tag_end+1:close_tag].strip()
                    # Icon patterns: single char, svg, emoji, short text
                    if len(inner) <= 3 or inner.startswith('{') or 'svg' in inner.lower():
                        print(f"\n{f}:{i+1}")
                        print(f"  {stripped[:120]}")
                        if len(block_lines) > 1:
                            print(f"  ... {block_lines[1][:80]}")
